// BAD: hidden O(n^2) — scan all customers for every order
function attachNames(orders, customers) {
  return orders.map(o => {
    const c = customers.find(c => c.id === o.customerId); // O(n) scan
    return { ...o, name: c.name };
  });
} // 5,000 orders x 5,000 scan = 25,000,000 comparisons

// GOOD: O(n) — build the lookup once, then O(1) per order
function attachNamesFast(orders, customers) {
  const byId = new Map(customers.map(c => [c.id, c.name])); // O(n) once
  return orders.map(o => ({ ...o, name: byId.get(o.customerId) })); // O(1) each
}

// Struct-of-Arrays: the field we sum is contiguous -> cache-friendly
struct Particles { float *x, *y, *z; };

float sum_x(struct Particles p, int n) {
    float s = 0;
    for (int i = 0; i < n; i++)
        s += p.x[i];      // sequential reads, prefetched, ~no misses
    return s;
}

