-- Effective-once at the endpoint that owns the balance.
-- Client sends the SAME Idempotency-Key on every retry.
BEGIN;

  -- 1. Claim the key. UNIQUE constraint = the dedup gate.
  INSERT INTO idempotency_records (key, status)
  VALUES ($idem_key, 'in_progress')
  ON CONFLICT (key) DO NOTHING;

  -- If 0 rows inserted, key was seen before -> return stored result:
  --   SELECT response FROM idempotency_records WHERE key = $idem_key;
  --   ROLLBACK;  (no new effect)

  -- 2. The effect, in the SAME transaction as the claim.
  UPDATE accounts
     SET balance_cents = balance_cents - $amount
   WHERE id = $account_id;

  -- 3. Persist the result so retries are answered identically.
  UPDATE idempotency_records
     SET status = 'done', response = $response_json
   WHERE key = $idem_key;

COMMIT;

